import {escapeHTML as esc} from './core.js';
import {listImports,saveImport,normaliseFeatures} from './custom-data.js';
const $=id=>document.getElementById(id);let current=null,source='',status='PARTIAL',tree;function message(s){$('ingest-status').textContent=s}
function preview(){const f=current?.features||[];$('preview-count').textContent=f.length+' enregistrements reçus · '+f.filter(x=>x.geometry).length+' géométries · '+status;$('preview').innerHTML=f.slice(0,8).map(x=>'<pre>'+esc(JSON.stringify(x.properties,null,2))+'</pre>').join('');$('save-data').disabled=!current}
function csv(text){const rows=[];let row=[],field='',quoted=false;const separator=text.split('\n')[0].includes(';')?';':',';for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(ch===separator&&!quoted){row.push(field);field=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x))rows.push(row);row=[];field=''}else field+=ch}if(field||row.length){row.push(field);rows.push(row)}const headers=rows.shift().map(x=>x.replace(/^\uFEFF/,'').trim());return {type:'FeatureCollection',features:rows.map(cells=>{const properties=Object.fromEntries(headers.map((h,i)=>[h,cells[i]??'']));const x=properties[$('lon').value],y=properties[$('lat').value],valid=x!==undefined&&y!==undefined&&x.trim()!==''&&y.trim()!==''&&Number.isFinite(Number(x))&&Number.isFinite(Number(y));return {type:'Feature',geometry:valid?{type:'Point',coordinates:[Number(x),Number(y)]}:null,properties}})}}
$('file').onchange=async()=>{try{const file=$('file').files[0];if(!file)return;if(file.size>20_000_000)throw Error('Fichier limité à 20 Mo dans cette interface.');const text=await file.text();current=normaliseFeatures(file.name.toLowerCase().endsWith('.csv')?csv(text):JSON.parse(text));source=file.name;status='COMPLETE';$('display-name').value||=file.name.replace(/\.[^.]+$/,'');preview();message('Fichier réel chargé. Vérifier le classement avant ajout.')}catch(e){current=null;preview();message(e.message)}};
function publicURL(){const u=new URL($('api-url').value);if(u.protocol!=='https:'||u.username||u.password||/localhost|\.local$|^127\.|^10\.|^192\.168\.|^\[/.test(u.hostname))throw Error('URL HTTPS publique attendue.');for(const k of u.searchParams.keys())if(/key|token|password|secret|signature/i.test(k))throw Error('Ne pas enregistrer de secret dans une URL du catalogue.');return u}
$('fetch-api').onclick=async()=>{message('Collecte des données réelles…');$('fetch-api').disabled=true;try{const u=publicURL();let data;const health=await fetch('api/health').then(r=>r.json()).catch(()=>null);if(health?.status==='ok'){const r=await fetch('api/ingest/fetch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:u.href,type_name:$('type-name').value})});data=await r.json();if(!r.ok)throw Error(data.detail)}else{if($('type-name').value){for(const [k,v] of Object.entries({SERVICE:'WFS',REQUEST:'GetFeature',VERSION:'2.0.0',TYPENAMES:$('type-name').value,COUNT:'10000',SRSNAME:'EPSG:4326',OUTPUTFORMAT:'application/json'}))u.searchParams.set(k,v)}const r=await fetch(u.href);if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();const fc=normaliseFeatures(d);const total=d.numberMatched??d.totalFeatures??d.total_count;data={data:fc,status:Number(total)===fc.features.length?'COMPLETE':'PARTIAL',note:'Total non annoncé = partiel. Pour WFS GML ou un blocage CORS, lancer le service local.'}}current=normaliseFeatures(data.data);source=$('api-url').value;status=data.status;preview();message(data.note||'Instantané reçu ; vérifier les limites et le classement.')}catch(e){current=null;preview();message(e.message+' Si le navigateur bloque CORS ou le format GML, utiliser le service local fourni.')}finally{$('fetch-api').disabled=false}};
$('reference-api').onclick=()=>{try{source=publicURL().href;current={type:'FeatureCollection',features:[]};status='REFERENCE';preview();message('Référence seule : aucune donnée collectée. Vous pouvez l’enregistrer avec cette mention.')}catch(e){message(e.message)}};
$('save-data').onclick=async()=>{try{if(!current)throw Error('Charger des données ou choisir Référence seule.');if(!$('display-name').value.trim()||!$('group').value.trim())throw Error('Nom affiché et groupe obligatoires.');if($('variant-type').value!=='none'&&!$('variant-value').value.trim())throw Error('Valeur de variante obligatoire.');const id='user_'+crypto.randomUUID();const data={...current,features:current.features.map((f,i)=>({...f,id:id+':'+i,properties:{...(f.properties||{}),_id:id+':'+i,_layer:id}}))};await saveImport({metadata:{id,display_name:$('display-name').value.trim(),theme:$('theme').value,group:$('group').value.trim(),source,status,updated:new Date().toISOString(),license:$('license').value,description:$('description').value,variant_type:$('variant-type').value,variant_value:$('variant-type').value==='none'?null:$('variant-value').value.trim()},data});message('Import enregistré. Ouvrir ou recharger l’Atlas pour le voir.');await registry()}catch(e){message(e.message)}};
async function registry(){const records=await listImports();$('imports').innerHTML=records.length?records.map(d=>'<article><h3>'+esc(d.metadata.display_name)+'</h3><p class="micro">'+esc(d.metadata.theme)+' → '+esc(d.metadata.group)+' · '+d.data.features.length+' objets · '+esc(d.metadata.status)+'</p></article>').join(''):'<p class="micro">Aucun import utilisateur.</p>';return records}
$('export-imports').onclick=async()=>{const data=await registry(),u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='Renatura_imports_utilisateur.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
try{tree=await fetch('data/atlas/catalog-v2.json').then(r=>r.json());$('theme').innerHTML=tree.themes.map(t=>'<option value="'+esc(t.id)+'">'+esc(t.display_name)+'</option>').join('');const groups=()=>{$('groups').innerHTML=(tree.themes.find(t=>t.id===$('theme').value)?.groups||[]).map(g=>'<option value="'+esc(g.display_name)+'">').join('')};$('theme').onchange=groups;groups();await registry()}catch(e){message(e.message)}
